369	    /// Maximum number of scroll pages to fetch. `None` means no limit.
370	    pub max_pages: Option<usize>,
371	    /// Records per emitted [`StreamPage`](faucet_core::StreamPage), which is
372	    /// also the `size` parameter passed to the Elasticsearch scroll API
