380	    /// small indices or for sinks (e.g. SQL `COPY`, BigQuery load jobs) that
381	    /// prefer one large request to many small ones. Indices that have raised
382	    /// their `max_result_window` will still cap at 10_000 — raise this knob
383	    /// or switch back to scroll if you need more.
384	    #[serde(default = "default_batch_size")]
