534	/// Format of files stored in GCS.
535	#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
536	#[serde(rename_all = "snake_case")]
537	pub enum GcsFileFormat {
538	    /// Each line in the file is a separate JSON record.
539	    #[default]
540	    JsonLines,
541	    /// The entire file is a JSON array of records.
542	    JsonArray,
543	    /// Each file becomes a single record with `"key"` and `"content"` fields.
544	    RawText,
545	    /// Apache Parquet objects. Decoded via the Arrow Parquet reader; the
546	    /// resulting `RecordBatch`es feed both the row path (converted to JSON)
547	    /// and the **columnar** fast path
548	    /// ([`Source::stream_batches`](faucet_core::Source::stream_batches)) so a
549	    /// `gcs(parquet) → parquet`/`delta` chain never materializes
550	    /// `serde_json::Value`. Requires the crate-local `arrow` feature
551	    /// (RFC 0002 / #375).
552	    #[cfg(feature = "arrow")]
553	    Parquet,
554	}
555	
556	/// Configuration for the GCS source connector.
557	#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
558	pub struct GcsSourceConfig {
559	    /// GCS bucket name.
560	    pub bucket: String,
561	    /// Object name prefix filter. Ignored when `object_keys` is set.
562	    pub prefix: Option<String>,
563	    /// Explicit object names. When set, listing is skipped and `prefix`
564	    /// is ignored.
565	    pub object_keys: Option<Vec<String>>,
566	    /// Credential source.
567	    #[serde(default)]
568	    pub auth: GcsCredentials,
569	    /// File format.
570	    #[serde(default)]
571	    pub file_format: GcsFileFormat,
572	    /// Hard cap on the number of objects read (after listing).
573	    pub max_objects: Option<usize>,
574	    /// Maximum concurrent object reads (default: 10).
575	    #[serde(default = "default_concurrency")]
576	    pub concurrency: usize,
577	    /// Records per emitted `StreamPage`. See "Streaming and batching"
578	    /// in the README. `batch_size = 0` is the "no batching" sentinel and
579	    /// emits one page per object.
580	    #[serde(default = "default_batch_size")]
581	    pub batch_size: usize,
582	    /// Verify each object's byte length against the `size` GCS reports for it,
583	    /// failing the read with [`FaucetError::Source`](faucet_core::FaucetError::Source)
584	    /// on a short (truncated) or over-long transfer (#161). Cheap (a byte
585	    /// counter over the body that is read anyway) and defaults to `true`.
586	    /// The check is automatically skipped for an object served with a
587	    /// non-empty `Content-Encoding` (GCS may decompressively transcode it on
588	    /// read, so the received byte count would not match the stored `size`).
589	    #[serde(default = "default_true")]
590	    pub verify_length: bool,
591	    /// Verify each object's body against the CRC32C (or MD5) checksum GCS
592	    /// reports for it (#161). Stronger than the length check but costs a hash
593	    /// over the full body, so it defaults to `false`. Skipped for an object
594	    /// with no usable checksum or one served with a non-empty
595	    /// `Content-Encoding` (the stored checksum covers the stored bytes, which
596	    /// transcoding would not return).
597	    #[serde(default)]
598	    pub verify_checksum: bool,
599	    /// Optional storage-host override (e.g. `http://localhost:4443` for
600	    /// fake-gcs-server). Production users should leave this unset.
601	    pub storage_host: Option<String>,
602	    /// Compression codec applied to each downloaded object. Defaults to
603	    /// [`CompressionConfig::Auto`](faucet_core::CompressionConfig::Auto) —
604	    /// the codec is resolved per-object-key, so a single source can read a
605	    /// mix of compressed and uncompressed objects. Requires the
606	    /// crate-local `compression` feature.
607	    #[cfg(feature = "compression")]
608	    #[serde(default)]
609	    pub compression: faucet_core::CompressionConfig,
610	}
