826	/// Authentication for GraphQL endpoints.
827	#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
828	#[serde(tag = "type", content = "config", rename_all = "snake_case")]
829	pub enum GraphqlAuth {
830	    /// No authentication.
831	    None,
832	    /// Bearer token in the Authorization header.
833	    Bearer { token: String },
834	    /// Custom headers (e.g. API keys, cookies).
835	    Custom { headers: HashMap<String, String> },
836	}
837	
838	/// Cursor-based pagination configuration for GraphQL.
839	///
840	/// Most GraphQL APIs use the Relay cursor specification with
841	/// `pageInfo { hasNextPage, endCursor }`.
842	#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
843	pub struct GraphqlPagination {
844	    /// JSONPath to the `hasNextPage` boolean in the response.
845	    pub has_next_page_path: String,
846	    /// JSONPath to the `endCursor` string in the response.
847	    pub cursor_path: String,
848	    /// Name of the cursor variable in the GraphQL query (default: `"after"`).
849	    pub cursor_variable: String,
850	    /// Name of the page size variable (default: `"first"`).
851	    ///
852	    /// The per-page record count itself comes from
853	    /// [`GraphqlStreamConfig::batch_size`] — the variable named here is the
854	    /// GraphQL variable that the `batch_size` value is injected into on each
855	    /// request. The plain `batch_size = 0` sentinel omits the variable so the
856	    /// upstream uses its own default page size.
857	    pub page_size_variable: String,
858	}
859	
860	impl Default for GraphqlPagination {
861	    fn default() -> Self {
862	        Self {
863	            has_next_page_path: "$.data.*.pageInfo.hasNextPage".into(),
864	            cursor_path: "$.data.*.pageInfo.endCursor".into(),
865	            cursor_variable: "after".into(),
866	            page_size_variable: "first".into(),
867	        }
868	    }
869	}
